#pragma material(ShadingModel = Unlit, Backend = ThinCustom)

uniform float3 Tint = float3(1.0, 0.5, 0.25);
uniform float Boost = 0.5;

export void M_RtThinCustom(inout material m)
{
    m.EmissiveColor = Tint * Boost;
}

#pragma layout(Node, Var = Boost, X = 90, Y = -180)
#pragma layout(Node, Var = Tint, X = 0, Y = -620)
